// The installer (install.js, generated by app-blueprints repo-site): a first install next to itself in iCloud Drive,
// "up to date", an update over an older copy, a bad download that changes nothing, and a phone without iCloud.
const { run, until } = require("../harness");
(async () => {
  const errors = [];
  process.on("unhandledRejection", (e) => errors.push("UNHANDLED " + (e && e.stack || e)));
  const SCRIPT = "// VisionX\nconst VERSION = '1.30.0';\nconst APP_ID = 'visionx';\n";
  const install = async (o) => {
    const { E, p } = await run(Object.assign({ script: "install.js", newScript: SCRIPT, alertValues: [{ action: 0 }] }, o));
    await p.catch((e) => errors.push("SCRIPT " + e.stack));
    errors.push(...E.problems());
    return E;
  };
  const target = (E) => E.env.module.filename.replace(/[^/]+$/, "VisionX.js");
  let E = await install({});
  console.log("A first install:", E.log.alerts.map((a) => a.title + " [" + a.actions.join(",") + "]").join(" | "), "| written to iCloud Drive:", E.files[target(E)] === SCRIPT, "| opened:", E.log.opened.join(","));
  E = await install({ files: E.files });
  console.log("B again, same file:", E.log.alerts[0].title, "|", E.log.alerts[0].message);
  E.files[target(E)] = "// VisionX\nconst VERSION = '1.20.0';\nconst APP_ID = 'visionx';\n";
  E = await install({ files: E.files, alertValues: [{ cancel: true }] });
  console.log("C over an older copy:", E.log.alerts[0].title, "|", E.log.alerts[0].message.slice(0, 60), "| Later: nothing opened", E.log.opened.length === 0, "| updated:", E.files[target(E)] === SCRIPT);
  const before = E.files[target(E)];
  E = await install({ files: E.files, newScript: "<html>Not Found</html>", newScriptStatus: 404 });
  console.log("D bad download:", E.log.alerts[0].title, "|", E.log.alerts[0].message, "| untouched:", E.files[target(E)] === before);
  E = await install({ offline: true });
  console.log("  offline:", E.log.alerts[0].title, "|", E.log.alerts[0].message.split("\n")[0]);
  E = await install({ noICloud: true });
  console.log("E no iCloud: installed on the phone", E.files[target(E)] === SCRIPT, "| path:", target(E).replace(E.path.local, "<local Documents>"), "| iCloud calls:", E.log.icloudTouched.length);
  console.log("errors:", errors.length ? errors.join(" | ") : "none", "| JS errors:", E.log.jsErrors || "none");
  process.exit(0);
})().catch((e) => { console.log("CRASH", e.stack); process.exit(1); });
